import { Component } from '@angular/core';
import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';

@Component({
  selector: 'app-all-jobs',
  templateUrl: './all-jobs.component.html',
  styleUrls: ['./all-jobs.component.css']
})
export class AllJobsComponent {

  constructor(private jobService: JobService ,private router:Royte) {}

  allJobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';

  ngOnInit() {

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');

      if (role === 'COMPANY') {

        this.profileRoute = '/company-dashboard';

        const companyName = localStorage.getItem('companyName');

        if (companyName) {
          this.initials = companyName
            .split(' ')
            .map(x => x[0])
            .join('')
            .substring(0, 2)
            .toUpperCase();
        }

      } else {

        this.profileRoute = '/jobseeker-dashboard';

        const userName = localStorage.getItem('userName');

        if (userName) {
          this.initials = userName
            .split(' ')
            .map(x => x[0])
            .join('')
            .substring(0, 2)
            .toUpperCase();
        }
      }
    }

    this.getAllJobs();
  }

  getAllJobs() {
    this.jobService.getAllJobs().subscribe(
      (res) => this.allJobs = res
    );
  }

  logout(){

  }

}
